from collections import Counter

def transform(grid):
    h, w = len(grid), len(grid[0])
    full_lines = []
    for r in range(h):
        if len(set(grid[r])) == 1:
            full_lines.append(grid[r][0])
    for c in range(w):
        vals = {grid[r][c] for r in range(h)}
        if len(vals) == 1:
            full_lines.append(next(iter(vals)))
    sep = Counter(full_lines).most_common(1)[0][0]

    row_seps = [r for r in range(h) if all(v == sep for v in grid[r])]
    col_seps = [c for c in range(w) if all(grid[r][c] == sep for r in range(h))]

    nonsep = [grid[r][c] for r in range(h) for c in range(w)
              if grid[r][c] != sep]
    base = Counter(nonsep).most_common(1)[0][0]

    row_bounds = [-1] + row_seps + [h]
    col_bounds = [-1] + col_seps + [w]
    out = []
    for i in range(len(row_bounds) - 1):
        row = []
        for j in range(len(col_bounds) - 1):
            count = sum(
                grid[r][c] != base and grid[r][c] != sep
                for r in range(row_bounds[i] + 1, row_bounds[i + 1])
                for c in range(col_bounds[j] + 1, col_bounds[j + 1])
            )
            row.append(1 if count == 2 else base)
        out.append(row)
    return out
